export type { PrimeReactIsolationOption, IsolationOptions } from '@primereact/types/core';
/**
 * Isolated mode for `PrimeReactProvider`: the app gets its own theme runtime and key, its styles go only
 * to the document and shadow roots it renders in, scoped to `[data-p-theme="<key>"]`.
 *
 * @example
 * <PrimeReactProvider theme={{ preset: Aura }} isolation={withIsolation({ key: 'shop' })}>
 *
 * @example
 * createRoot(container).render(<PrimeReactProvider theme={theme} isolation={withIsolation({ key: 'orders', root: container })}><App /></PrimeReactProvider>);
 *
 * @throws TypeError when `key` is not 1 to 128 letters, digits, `_` or `-`, or `root` is not an element.
 * @experimental
 */
export declare function withIsolation(options?: IsolationOptions): PrimeReactIsolationOption;
